import{_ as t,o as _,c as a,a4 as r}from"./chunks/framework.C3unmAF4.js";const i=JSON.parse('{"title":"（乡村行·看振兴）山西繁峙：“荒沟沟”长出“致富粮” 数字农业激活乡村振兴新引擎","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"（乡村行·看振兴）山西繁峙：“荒沟沟”长出“致富粮” 数字农业激活乡村振兴新引擎","date":"2026-09-02T00:00:00.000Z","source":"农业农村部智慧农业专题","category":"news","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202608/t20260831_6487155.htm","summary":"中新网\\n忻州8月25日电 题:山西繁峙:“荒沟沟”长出“致富粮” 数字农业激活乡村振兴新引擎\\n作者 杨静 钟昱星\\n夏末秋初,走进山西省忻州市繁峙县集义庄乡宏旺村,昔日杂草丛生、坑洼不平的荒沟荒坡已不见踪影。眼前,百亩杂粮种植基地规整连片,沟渠管网排布有序,三通道水肥一体化智能设备正精准调控田间水肥,现代农业气息扑面而来。\\n“以前这里土质贫瘠、灌溉困难,几乎没什么种植收益。...\\n","contentHash":"e22f4f8f3b360c573bf1842443159542","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-09-02-乡村行-看振兴-山西繁峙-荒沟沟-长出-致富粮-数字农业激活乡村振兴新引擎.md","filePath":"news/2026-09-02-乡村行-看振兴-山西繁峙-荒沟沟-长出-致富粮-数字农业激活乡村振兴新引擎.md"}'),n={name:"news/2026-09-02-乡村行-看振兴-山西繁峙-荒沟沟-长出-致富粮-数字农业激活乡村振兴新引擎.md"};function s(p,e,o,l,d,c){return _(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="乡村行·看振兴-山西繁峙-荒沟沟-长出-致富粮-数字农业激活乡村振兴新引擎" tabindex="-1">（乡村行·看振兴）山西繁峙：“荒沟沟”长出“致富粮” 数字农业激活乡村振兴新引擎 <a class="header-anchor" href="#乡村行·看振兴-山西繁峙-荒沟沟-长出-致富粮-数字农业激活乡村振兴新引擎" aria-label="Permalink to &quot;（乡村行·看振兴）山西繁峙：“荒沟沟”长出“致富粮” 数字农业激活乡村振兴新引擎&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202608/t20260831_6487155.htm" target="_blank" rel="noreferrer">农业农村部智慧农业专题</a><br> 日期: 2026-09-02 摘要: 中新网 忻州8月25日电 题:山西繁峙:“荒沟沟”长出“致富粮” 数字农业激活乡村振兴新引擎 作者 杨静 钟昱星 夏末秋初,走进山西省忻州市繁峙县集义庄乡宏旺村,昔日杂草丛生、坑洼不平的荒沟荒坡已不见踪影。眼前,百亩杂粮种植基地规整连片,沟渠管网排布有序,三通道水肥一体化智能设备正精准调控田间水肥,现代农业气息扑面而来。 “以前这里土质贫瘠、灌溉困难,几乎没什么种植收益。...</p></blockquote><p>作者 杨静 钟昱星</p><p>夏末秋初,走进山西省忻州市繁峙县集义庄乡宏旺村,昔日杂草丛生、坑洼不平的荒沟荒坡已不见踪影。眼前,百亩杂粮种植基地规整连片,沟渠管网排布有序,三通道水肥一体化智能设备正精准调控田间水肥,现代农业气息扑面而来。</p><p>“以前这里土质贫瘠、灌溉困难,几乎没什么种植收益。”望着焕然一新的农田,宏旺村村委会副主任陈科感慨。这片土地的蜕变,正是当地以数字科技赋能传统农业、以精准帮扶助力乡村振兴的实践。</p><p>陈科介绍,通过数字化改造与标准化提质,村里百余亩贫瘠荒地成功转型为高标准水浇良田,土地利用率、耕地产出率双双提升,扭转了传统农业粗放低效的局面,为产业提质、民众增收打下基础。</p><p>宏旺村地处集义庄乡东北部,750亩耕地中生态公益林占614.7亩,实际可耕作土地有限,且地形复杂、基础设施薄弱,传统种植效益低下。2025年村集体经济收入仅9万元,全依赖光伏产业,村民多外出务工,本地就业机会匮乏。</p><p>为破解发展瓶颈,集义庄乡将数字智慧农业作为产业破局、耕地提质、民众增收的重要抓手。在国家体育总局帮扶支持下,2025年,宏旺村启动数字农业项目——百亩杂粮高标准种植示范基地,推动农业向标准化、智能化、集约化转型。</p><p>据介绍,该项目总投资186.36万元。建设期间,乡村两级通过土地平整、沟渠修缮等将118亩荒沟地块改造为高标准水浇地,同步配套三通道水肥一体化智能系统,实现精准灌溉施肥,资源利用率大幅提升。</p><p>数字赋能唤醒了“沉睡”土地。2026年,示范基地规模化种植了谷子、黍米、藜麦等本地优质杂粮。项目稳定运行后,预计每年可为村集体新增收5万元以上。同时,可常年吸纳村内10名左右剩余劳动力就近就业,带动村民人均年增收0.6万元。</p><p>“下一步,乡里将持续做优做强数字农业示范样板,推广智慧种植技术,健全完善联农带农长效机制,盘活乡村闲置资源,拓宽民众增收致富渠道,以数字农业产业化发展助力乡村高质量发展。”集义庄乡副乡长左亚东说。(完)</p><p><a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202608/t20260831_6487155.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',12)])])}const h=t(n,[["render",s]]);export{i as __pageData,h as default};
